import { Card, BlockStack, InlineStack, Text, Badge } from "@shopify/polaris";

interface StatCardTrend {
  value: number;
  positive: boolean;
}

interface StatCardProps {
  title: string;
  value: string | number;
  subtitle?: string;
  trend?: StatCardTrend;
}

export function StatCard({ title, value, subtitle, trend }: StatCardProps) {
  const trendLabel =
    trend !== undefined
      ? `${trend.positive ? "+" : ""}${trend.value}%`
      : undefined;

  return (
    <Card>
      <BlockStack gap="100">
        <Text as="h2" variant="headingXl" fontWeight="bold">
          {typeof value === "number" ? value.toLocaleString() : value}
        </Text>
        <Text as="p" variant="bodyMd" tone="subdued">
          {title}
        </Text>
        {(subtitle || trend) && (
          <InlineStack gap="200" blockAlign="center">
            {subtitle && (
              <Text as="p" variant="bodyMd" tone="subdued">
                {subtitle}
              </Text>
            )}
            {trend && trendLabel && (
              <Badge tone={trend.positive ? "success" : "critical"}>
                {trendLabel} vs last month
              </Badge>
            )}
          </InlineStack>
        )}
      </BlockStack>
    </Card>
  );
}

