import { useState } from "react";

interface BarChartDataPoint {
  label: string;
  value: number;
}

interface BarChartProps {
  data: BarChartDataPoint[];
  height?: number;
  barColor?: string;
  showLabels?: boolean;
}

const GRID_LINES = [0.25, 0.5, 0.75, 1];
const LABEL_AREA_HEIGHT = 36;
const Y_AXIS_WIDTH = 40;
const BAR_GAP_RATIO = 0.3; // 30% of available slot is gap

export function BarChart({
  data,
  height = 200,
  barColor = "#2c6ecb",
  showLabels = true,
}: BarChartProps) {
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);

  if (data.length === 0) {
    return (
      <svg
        width="100%"
        height={height + (showLabels ? LABEL_AREA_HEIGHT : 0)}
        aria-label="Bar chart — no data"
      />
    );
  }

  const maxValue = Math.max(...data.map((d) => d.value), 1);
  const chartHeight = height;
  const totalHeight = chartHeight + (showLabels ? LABEL_AREA_HEIGHT : 0);

  return (
    <svg
      width="100%"
      viewBox={`0 0 ${400 + Y_AXIS_WIDTH} ${totalHeight}`}
      preserveAspectRatio="none"
      style={{ display: "block", width: "100%" }}
      aria-label="Bar chart"
    >
      {/* Grid lines */}
      {GRID_LINES.map((fraction) => {
        const y = chartHeight - fraction * chartHeight;
        const gridValue = Math.round(maxValue * fraction);
        return (
          <g key={fraction}>
            <line
              x1={Y_AXIS_WIDTH}
              y1={y}
              x2={400 + Y_AXIS_WIDTH}
              y2={y}
              stroke="#e3e3e3"
              strokeWidth={1}
            />
            <text
              x={Y_AXIS_WIDTH - 4}
              y={y + 4}
              textAnchor="end"
              fontSize={10}
              fill="#8c9196"
            >
              {gridValue.toLocaleString()}
            </text>
          </g>
        );
      })}

      {/* Bars */}
      {data.map((point, i) => {
        const slotWidth = 400 / data.length;
        const barWidth = slotWidth * (1 - BAR_GAP_RATIO);
        const x = Y_AXIS_WIDTH + i * slotWidth + (slotWidth - barWidth) / 2;
        const barHeight = (point.value / maxValue) * chartHeight;
        const y = chartHeight - barHeight;
        const isHovered = hoveredIndex === i;

        return (
          <g key={i}>
            <rect
              x={x}
              y={y}
              width={barWidth}
              height={barHeight}
              fill={isHovered ? "#1a4f9b" : barColor}
              rx={2}
              onMouseEnter={() => setHoveredIndex(i)}
              onMouseLeave={() => setHoveredIndex(null)}
              style={{ cursor: "default", transition: "fill 0.1s ease" }}
            />

            {/* Tooltip on hover */}
            {isHovered && (
              <g>
                <rect
                  x={x + barWidth / 2 - 28}
                  y={Math.max(y - 28, 2)}
                  width={56}
                  height={20}
                  rx={3}
                  fill="#202223"
                />
                <text
                  x={x + barWidth / 2}
                  y={Math.max(y - 13, 17)}
                  textAnchor="middle"
                  fontSize={10}
                  fill="#ffffff"
                >
                  {point.value.toLocaleString()}
                </text>
              </g>
            )}

            {/* X-axis label */}
            {showLabels && (
              <text
                x={x + barWidth / 2}
                y={chartHeight + 16}
                textAnchor="end"
                fontSize={10}
                fill="#8c9196"
                transform={`rotate(-45, ${x + barWidth / 2}, ${
                  chartHeight + 16
                })`}
              >
                {point.label}
              </text>
            )}
          </g>
        );
      })}

      {/* X-axis base line */}
      <line
        x1={Y_AXIS_WIDTH}
        y1={chartHeight}
        x2={400 + Y_AXIS_WIDTH}
        y2={chartHeight}
        stroke="#e3e3e3"
        strokeWidth={1}
      />
    </svg>
  );
}

import { BlockStack, InlineStack, Text } from "@shopify/polaris";

interface FunnelStep {
  label: string;
  value: number;
  color?: string;
}

interface FunnelBarProps {
  steps: FunnelStep[];
}

const DEFAULT_COLORS = ["#2c6ecb", "#5c8fe8", "#8ab4f0", "#b9d1f7"];

export function FunnelBar({ steps }: FunnelBarProps) {
  if (steps.length === 0) {
    return null;
  }

  const maxValue = steps[0].value;

  return (
    <BlockStack gap="300">
      {steps.map((step, i) => {
        const pct = maxValue > 0 ? Math.round((step.value / maxValue) * 100) : 0;
        const color = step.color ?? DEFAULT_COLORS[i % DEFAULT_COLORS.length];

        return (
          <BlockStack key={i} gap="100">
            <InlineStack align="space-between" blockAlign="center">
              <Text as="span" variant="bodyMd" tone="subdued">
                {step.label}
              </Text>
              <InlineStack gap="200" blockAlign="center">
                <Text as="span" variant="bodyMd" fontWeight="semibold">
                  {step.value.toLocaleString()}
                </Text>
                <Text as="span" variant="bodySm" tone="subdued">
                  {pct}%
                </Text>
              </InlineStack>
            </InlineStack>

            {/* Bar track */}
            <div
              style={{
                height: "8px",
                borderRadius: "4px",
                backgroundColor: "#f1f2f3",
                overflow: "hidden",
              }}
            >
              <div
                style={{
                  height: "100%",
                  width: `${pct}%`,
                  borderRadius: "4px",
                  backgroundColor: color,
                  transition: "width 0.3s ease",
                }}
              />
            </div>
          </BlockStack>
        );
      })}
    </BlockStack>
  );
}

export { StatCard } from "./StatCard";
export { EmptyStateCard } from "./EmptyStateCard";
export { PlanGate } from "./PlanGate";
export { BarChart } from "./BarChart";
