import { useState } from "react";
import type { LoaderFunctionArgs } from "react-router";
import { useLoaderData, useNavigate } from "react-router";
import {
  Page,
  Layout,
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  Box,
  Divider,
  InlineGrid,
  ProgressBar,
  List,
  Banner,
} from "@shopify/polaris";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import { getPlan } from "../lib/plans";
import { StatCard } from "../components";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function formatDate(date: string | Date): string {
  const d = typeof date === "string" ? new Date(date) : date;
  return d.toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
}

function calcTrend(
  current: number,
  previous: number,
): { value: number; positive: boolean } | undefined {
  if (previous === 0) return undefined;
  const delta = Math.round(((current - previous) / previous) * 100);
  return { value: Math.abs(delta), positive: delta >= 0 };
}

// ---------------------------------------------------------------------------
// Loader
// ---------------------------------------------------------------------------

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const now = new Date();
  const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
  const sixtyDaysAgo = new Date(now.getTime() - 60 * 24 * 60 * 60 * 1000);

  const [
    chartCount,
    activeChartCount,
    draftChartCount,
    monthlyViews,
    totalRecommendations,
    previousViews,
    previousRecommendations,
    subscription,
    recentCharts,
    widgetConfig,
    recommenderConfig,
    assignmentCount,
  ] = await Promise.all([
    db.sizeChart.count({ where: { shop } }),
    db.sizeChart.count({ where: { shop, status: "active" } }),
    db.sizeChart.count({ where: { shop, status: "draft" } }),
    // Current 30-day views
    db.analyticsEvent.count({
      where: { shop, eventType: "view", createdAt: { gte: thirtyDaysAgo } },
    }),
    // All-time recommendations (last 30 days for consistency)
    db.analyticsEvent.count({
      where: { shop, eventType: "recommend", createdAt: { gte: thirtyDaysAgo } },
    }),
    // Previous 30-day views (days 31–60)
    db.analyticsEvent.count({
      where: {
        shop,
        eventType: "view",
        createdAt: { gte: sixtyDaysAgo, lt: thirtyDaysAgo },
      },
    }),
    // Previous 30-day recommendations (days 31–60)
    db.analyticsEvent.count({
      where: {
        shop,
        eventType: "recommend",
        createdAt: { gte: sixtyDaysAgo, lt: thirtyDaysAgo },
      },
    }),
    db.subscription.findUnique({ where: { shop } }),
    db.sizeChart.findMany({
      where: { shop },
      orderBy: { updatedAt: "desc" },
      take: 5,
      select: {
        id: true,
        name: true,
        category: true,
        status: true,
        updatedAt: true,
        _count: { select: { assignments: true } },
      },
    }),
    db.widgetConfig.findUnique({ where: { shop } }),
    db.recommenderConfig.findUnique({ where: { shop } }),
    db.chartAssignment.count({ where: { shop } }),
  ]);

  const plan = getPlan(subscription?.planId ?? "free");

  const hasChart = chartCount > 0;
  const hasAssignment = assignmentCount > 0;
  const hasWidget = widgetConfig !== null;
  const hasRecommender =
    recommenderConfig !== null && recommenderConfig.enabled;

  const setupSteps = [
    {
      key: "create-chart",
      title: "Create your first size chart",
      description:
        "Choose from 9 ready-made templates or build a custom chart from scratch.",
      done: hasChart,
      actionLabel: "Create chart",
      actionUrl: "/app/size-charts",
    },
    {
      key: "customize-widget",
      title: "Style your size chart widget",
      description:
        "Customize colors, layout, and text to match your store's brand.",
      done: hasWidget,
      actionLabel: "Go to Appearance",
      actionUrl: "/app/widget",
    },
    {
      key: "assign-products",
      title: "Assign chart to products",
      description:
        "Link your chart to products, collections, or tags so it shows automatically.",
      done: hasAssignment,
      actionLabel: "Assign products",
      actionUrl: "/app/size-charts",
    },
  ];

  const completedCount = setupSteps.filter((s) => s.done).length;

  return {
    shop,
    chartCount,
    activeChartCount,
    draftChartCount,
    monthlyViews,
    totalRecommendations,
    viewsTrend: calcTrend(monthlyViews, previousViews),
    recommendationsTrend: calcTrend(totalRecommendations, previousRecommendations),
    plan,
    recentCharts: recentCharts.map((c) => ({
      ...c,
      assignmentCount: c._count.assignments,
      updatedAt: c.updatedAt.toISOString(),
    })),
    hasRecommender,
    setupSteps,
    completedCount,
    totalSteps: setupSteps.length,
  };
};

// ---------------------------------------------------------------------------
// Step circle
// ---------------------------------------------------------------------------

function StepCircle({ done }: { done: boolean }) {
  return (
    <Box
      width="24px"
      minHeight="24px"
      borderRadius="full"
      borderWidth={done ? "0" : "025"}
      borderColor={done ? undefined : "border"}
      background={done ? "bg-fill-emphasis" : "bg-surface"}
    >
      <InlineStack align="center" blockAlign="center">
        {done && (
          <Text as="span" variant="bodySm" fontWeight="bold" tone="text-inverse">
            ✓
          </Text>
        )}
      </InlineStack>
    </Box>
  );
}

// ---------------------------------------------------------------------------
// Quick action card
// ---------------------------------------------------------------------------

interface QuickActionCardProps {
  title: string;
  description: string;
  actionLabel: string;
  onAction: () => void;
}

function QuickActionCard({
  title,
  description,
  actionLabel,
  onAction,
}: QuickActionCardProps) {
  return (
    <Card>
      <BlockStack gap="300">
        <BlockStack gap="100">
          <Text as="h3" variant="headingMd" fontWeight="semibold">
            {title}
          </Text>
          <Text as="p" variant="bodyMd" tone="subdued">
            {description}
          </Text>
        </BlockStack>
        <Button onClick={onAction}>{actionLabel}</Button>
      </BlockStack>
    </Card>
  );
}

// ---------------------------------------------------------------------------
// App status row item
// ---------------------------------------------------------------------------

interface StatusRowProps {
  label: string;
  active: boolean;
  badge?: string;
}

function StatusRow({ label, active, badge }: StatusRowProps) {
  return (
    <Box
      padding="300"
      borderWidth="025"
      borderColor="border-secondary"
      borderRadius="200"
      background="bg-surface-secondary"
    >
      <InlineStack align="space-between" blockAlign="center">
        <InlineStack gap="200" blockAlign="center">
          <Text as="p" variant="bodyMd">
            {label}
          </Text>
          {badge && <Badge tone="new">{badge}</Badge>}
        </InlineStack>
        <Badge tone={active ? "success" : "enabled"}>
          {active ? "Active" : "Inactive"}
        </Badge>
      </InlineStack>
    </Box>
  );
}

// ---------------------------------------------------------------------------
// Dashboard component
// ---------------------------------------------------------------------------

export default function Dashboard() {
  const {
    chartCount,
    activeChartCount,
    draftChartCount,
    monthlyViews,
    totalRecommendations,
    viewsTrend,
    recommendationsTrend,
    plan,
    recentCharts,
    hasRecommender,
    setupSteps,
    completedCount,
    totalSteps,
  } = useLoaderData<typeof loader>();

  const navigate = useNavigate();

  const [setupOpen, setSetupOpen] = useState(true);
  const [expandedStep, setExpandedStep] = useState<string | null>(
    setupSteps.find((s) => !s.done)?.key ?? null,
  );

  const isSetupComplete = completedCount === totalSteps;
  const isFreePlan = plan.id === "free";
  const maxCharts = plan.limits.maxCharts;
  const setupProgressPct = Math.round((completedCount / totalSteps) * 100);
  const chartUsagePct =
    maxCharts > 0 ? Math.round((chartCount / maxCharts) * 100) : 0;

  return (
    <Page
      title="Dashboard"
      primaryAction={{
        content: "Create Size Chart",
        onAction: () => navigate("/app/size-charts"),
      }}
    >
      <Layout>
        {/* ================================================================ */}
        {/* SETUP GUIDE                                                        */}
        {/* ================================================================ */}
        {!isSetupComplete && (
          <Layout.Section>
            <Card>
              <BlockStack gap="400">
                <InlineStack align="space-between" blockAlign="center">
                  <BlockStack gap="100">
                    <Text as="h2" variant="headingMd" fontWeight="bold">
                      Setup guide
                    </Text>
                    <Text as="p" variant="bodyMd" tone="subdued">
                      Use this personalized guide to get your app running.
                    </Text>
                  </BlockStack>
                  <Button
                    variant="plain"
                    onClick={() => setSetupOpen(!setupOpen)}
                  >
                    {setupOpen ? "Hide" : "Show"}
                  </Button>
                </InlineStack>

                <BlockStack gap="100">
                  <Text as="p" variant="bodySm" tone="subdued">
                    {completedCount} of {totalSteps} steps completed
                  </Text>
                  <ProgressBar
                    progress={setupProgressPct}
                    tone="primary"
                    size="small"
                  />
                </BlockStack>

                {setupOpen && (
                  <BlockStack gap="200">
                    {setupSteps.map((step) => (
                      <Box
                        key={step.key}
                        padding="400"
                        borderWidth="025"
                        borderColor="border"
                        borderRadius="200"
                        background={
                          expandedStep === step.key
                            ? "bg-surface-hover"
                            : "bg-surface"
                        }
                      >
                        <div
                          role="button"
                          tabIndex={0}
                          onClick={() =>
                            setExpandedStep(
                              expandedStep === step.key ? null : step.key,
                            )
                          }
                          onKeyDown={(e) => {
                            if (e.key === "Enter" || e.key === " ") {
                              e.preventDefault();
                              setExpandedStep(
                                expandedStep === step.key ? null : step.key,
                              );
                            }
                          }}
                          style={{ cursor: "pointer" }}
                        >
                          <InlineStack gap="400" blockAlign="start">
                            <StepCircle done={step.done} />
                            <BlockStack gap="100">
                              <Text
                                as="p"
                                variant="bodyMd"
                                tone={step.done ? "subdued" : undefined}
                                textDecorationLine={
                                  step.done ? "line-through" : undefined
                                }
                              >
                                {step.title}
                              </Text>

                              {expandedStep === step.key && !step.done && (
                                <BlockStack gap="300">
                                  <Text as="p" variant="bodyMd" tone="subdued">
                                    {step.description}
                                  </Text>
                                  <Button
                                    variant="primary"
                                    onClick={() => navigate(step.actionUrl)}
                                  >
                                    {step.actionLabel}
                                  </Button>
                                </BlockStack>
                              )}
                            </BlockStack>
                          </InlineStack>
                        </div>
                      </Box>
                    ))}
                  </BlockStack>
                )}
              </BlockStack>
            </Card>
          </Layout.Section>
        )}

        {/* ================================================================ */}
        {/* STATS OVERVIEW                                                     */}
        {/* ================================================================ */}
        <Layout.Section>
          <InlineGrid columns={{ xs: 1, sm: 2, md: 4 }} gap="400">
            <StatCard
              title="Total charts"
              value={chartCount}
              subtitle={`${activeChartCount} active · ${draftChartCount} draft`}
            />
            <StatCard
              title="Published charts"
              value={activeChartCount}
              subtitle="Visible on storefront"
            />
            <StatCard
              title="Chart views"
              value={monthlyViews}
              subtitle="Last 30 days"
              trend={viewsTrend}
            />
            <StatCard
              title="AI recommendations"
              value={totalRecommendations}
              subtitle={plan.limits.aiRecommender ? "Last 30 days" : "Upgrade to unlock"}
              trend={plan.limits.aiRecommender ? recommendationsTrend : undefined}
            />
          </InlineGrid>
        </Layout.Section>

        {/* ================================================================ */}
        {/* QUICK ACTIONS                                                      */}
        {/* ================================================================ */}
        <Layout.Section>
          <BlockStack gap="300">
            <Text as="h2" variant="headingMd" fontWeight="bold">
              Quick actions
            </Text>
            <InlineGrid columns={{ xs: 1, sm: 3 }} gap="400">
              <QuickActionCard
                title="Create Size Chart"
                description="Choose from 9 templates or build a custom chart."
                actionLabel="New chart"
                onAction={() => navigate("/app/size-charts")}
              />
              <QuickActionCard
                title="Customize Widget"
                description="Match your store's brand with colors and layout."
                actionLabel="Edit appearance"
                onAction={() => navigate("/app/widget")}
              />
              <QuickActionCard
                title="View Analytics"
                description="Track chart performance and recommendation usage."
                actionLabel="Open analytics"
                onAction={() => navigate("/app/analytics")}
              />
            </InlineGrid>
          </BlockStack>
        </Layout.Section>

        {/* ================================================================ */}
        {/* EMPTY STATE BANNER — no charts yet                                */}
        {/* ================================================================ */}
        {chartCount === 0 && (
          <Layout.Section>
            <Banner tone="info" title="Show size charts for all your products">
              <BlockStack gap="400">
                <Text as="p" variant="bodyMd">
                  Help customers find the right size. Reduce returns by up to 40%.
                </Text>
                <InlineStack gap="400">
                  <Button
                    variant="primary"
                    onClick={() => navigate("/app/size-charts")}
                  >
                    Create chart
                  </Button>
                  <Button onClick={() => navigate("/app/pricing")}>
                    View plans
                  </Button>
                </InlineStack>
              </BlockStack>
            </Banner>
          </Layout.Section>
        )}

        {/* ================================================================ */}
        {/* RECENT SIZE CHARTS                                                 */}
        {/* ================================================================ */}
        <Layout.Section>
          <Card>
            <BlockStack gap="400">
              <InlineStack align="space-between" blockAlign="center">
                <Text as="h2" variant="headingMd" fontWeight="bold">
                  {chartCount > 0 ? "Recent size charts" : "No size charts yet"}
                </Text>
                {chartCount > 0 && (
                  <Button
                    variant="plain"
                    onClick={() => navigate("/app/size-charts")}
                  >
                    View all
                  </Button>
                )}
              </InlineStack>

              {recentCharts.length === 0 ? (
                <BlockStack gap="300" inlineAlign="center">
                  <Text as="p" variant="bodyMd" tone="subdued" alignment="center">
                    Create your first chart using one of 9 ready-made templates
                    or build your own from scratch.
                  </Text>
                  <Button
                    variant="primary"
                    onClick={() => navigate("/app/size-charts")}
                  >
                    Create a size chart
                  </Button>
                </BlockStack>
              ) : (
                <BlockStack gap="0">
                  {/* Column headers */}
                  <Box paddingBlockEnd="200">
                    <InlineGrid columns="1fr 120px 120px 90px 110px" gap="200">
                      <Text as="p" variant="bodySm" tone="subdued" fontWeight="medium">
                        Name
                      </Text>
                      <Text as="p" variant="bodySm" tone="subdued" fontWeight="medium">
                        Category
                      </Text>
                      <Text as="p" variant="bodySm" tone="subdued" fontWeight="medium">
                        Status
                      </Text>
                      <Text as="p" variant="bodySm" tone="subdued" fontWeight="medium">
                        Assigned
                      </Text>
                      <Text as="p" variant="bodySm" tone="subdued" fontWeight="medium" alignment="end">
                        Updated
                      </Text>
                    </InlineGrid>
                  </Box>

                  <Divider />

                  {recentCharts.map((chart, index) => (
                    <Box key={chart.id}>
                      {index > 0 && <Divider />}
                      <Box paddingBlock="300">
                        <InlineGrid
                          columns="1fr 120px 120px 90px 110px"
                          gap="200"
                        >
                          {/* Name */}
                          <Button
                            variant="plain"
                            textAlign="left"
                            onClick={() =>
                              navigate(`/app/size-charts/${chart.id}`)
                            }
                          >
                            {chart.name}
                          </Button>

                          {/* Category */}
                          <Box>
                            <Badge tone="info">{chart.category}</Badge>
                          </Box>

                          {/* Status */}
                          <Box>
                            <Badge
                              tone={
                                chart.status === "active" ? "success" : "enabled"
                              }
                            >
                              {chart.status === "active" ? "Active" : "Draft"}
                            </Badge>
                          </Box>

                          {/* Assignments */}
                          <Text as="p" variant="bodyMd" tone="subdued">
                            {chart.assignmentCount > 0
                              ? `${chart.assignmentCount} product${chart.assignmentCount !== 1 ? "s" : ""}`
                              : "None"}
                          </Text>

                          {/* Last updated */}
                          <Text
                            as="p"
                            variant="bodyMd"
                            tone="subdued"
                            alignment="end"
                          >
                            {formatDate(chart.updatedAt)}
                          </Text>
                        </InlineGrid>
                      </Box>
                    </Box>
                  ))}
                </BlockStack>
              )}
            </BlockStack>
          </Card>
        </Layout.Section>

        {/* ================================================================ */}
        {/* APP STATUS                                                         */}
        {/* ================================================================ */}
        <Layout.Section>
          <Card>
            <BlockStack gap="400">
              <BlockStack gap="100">
                <Text as="h2" variant="headingMd" fontWeight="bold">
                  App status
                </Text>
                <Text as="p" variant="bodyMd" tone="subdued">
                  Current state of your app components.
                </Text>
              </BlockStack>

              <BlockStack gap="200">
                <StatusRow
                  label="Widget"
                  active={activeChartCount > 0}
                />
                <StatusRow
                  label="AI Recommender"
                  active={hasRecommender}
                  badge={plan.limits.aiRecommender ? undefined : "Growth+"}
                />
                <Box
                  padding="300"
                  borderWidth="025"
                  borderColor="border-secondary"
                  borderRadius="200"
                  background="bg-surface-secondary"
                >
                  <InlineStack align="space-between" blockAlign="center">
                    <Text as="p" variant="bodyMd">
                      Charts published
                    </Text>
                    <Text as="p" variant="bodyMd" fontWeight="semibold">
                      {activeChartCount}
                    </Text>
                  </InlineStack>
                </Box>
              </BlockStack>
            </BlockStack>
          </Card>
        </Layout.Section>

        {/* ================================================================ */}
        {/* ASIDE — Plan & Usage, Quick links, Help                           */}
        {/* ================================================================ */}
        <Layout.Section variant="oneThird">
          <BlockStack gap="400">
            {/* Plan card */}
            <Card>
              <BlockStack gap="400">
                <Text as="h2" variant="headingMd" fontWeight="bold">
                  Your plan
                </Text>

                <InlineStack gap="200" blockAlign="center">
                  <Badge tone={isFreePlan ? "enabled" : "success"}>
                    {plan.name}
                  </Badge>
                  <Text as="p" variant="bodyMd" tone="subdued">
                    {plan.price === 0 ? "Free" : `$${plan.price}/mo`}
                  </Text>
                </InlineStack>

                {isFreePlan && maxCharts > 0 && (
                  <BlockStack gap="100">
                    <Text as="p" variant="bodySm" tone="subdued">
                      {chartCount} / {maxCharts} charts used
                    </Text>
                    <ProgressBar
                      progress={chartUsagePct}
                      tone={chartCount >= maxCharts ? "critical" : "highlight"}
                      size="small"
                    />
                  </BlockStack>
                )}

                <List>
                  {plan.features.slice(0, 4).map((f, i) => (
                    <List.Item key={i}>{f}</List.Item>
                  ))}
                </List>

                {isFreePlan && (
                  <Button
                    onClick={() => navigate("/app/pricing")}
                    variant="primary"
                  >
                    Upgrade plan
                  </Button>
                )}
              </BlockStack>
            </Card>

            {/* Quick links */}
            <Card>
              <BlockStack gap="400">
                <Text as="h2" variant="headingMd" fontWeight="bold">
                  Quick links
                </Text>
                <List>
                  <List.Item>
                    <Button
                      variant="plain"
                      onClick={() => navigate("/app/size-charts")}
                    >
                      Size Charts
                    </Button>
                  </List.Item>
                  <List.Item>
                    <Button
                      variant="plain"
                      onClick={() => navigate("/app/widget")}
                    >
                      Widget Appearance
                    </Button>
                  </List.Item>
                  <List.Item>
                    <Button
                      variant="plain"
                      onClick={() => navigate("/app/recommender")}
                    >
                      AI Recommender
                    </Button>
                  </List.Item>
                  <List.Item>
                    <Button
                      variant="plain"
                      onClick={() => navigate("/app/analytics")}
                    >
                      Analytics
                    </Button>
                  </List.Item>
                  <List.Item>
                    <Button
                      variant="plain"
                      onClick={() => navigate("/app/settings")}
                    >
                      Settings
                    </Button>
                  </List.Item>
                </List>
              </BlockStack>
            </Card>

            {/* Help */}
            <Card>
              <BlockStack gap="400">
                <Text as="h2" variant="headingMd" fontWeight="bold">
                  Need help?
                </Text>
                <Text as="p" variant="bodyMd" tone="subdued">
                  We respond within 2 hours.
                </Text>
                <List>
                  <List.Item>
                    <Button variant="plain" url="mailto:support@sizechart.app">
                      Email support
                    </Button>
                  </List.Item>
                  <List.Item>
                    <Button
                      variant="plain"
                      onClick={() => navigate("/app/settings")}
                    >
                      App settings
                    </Button>
                  </List.Item>
                </List>
                {plan.limits.prioritySupport && (
                  <Badge tone="success">Priority support active</Badge>
                )}
              </BlockStack>
            </Card>
          </BlockStack>
        </Layout.Section>
      </Layout>
    </Page>
  );
}
